/// `resolve_component`, plus what its resolution depended on. Watch mode re-resolves a component when one of those
/// changes.
pub(crate) fn resolve_component_tracked(
    mapping: &ComponentMapping,
    ctx: &ResolutionContext,
) -> (ComponentEntry, ResolvedDiagnostics, Dependencies, Option<Arc<crate::relevance::Inputs>>) {
    let ((entry, mut diagnostics, evidence), mut deps) = deps::recording(|| {
        let (entry, diagnostics) = resolve_component_shared(mapping, ctx);
        // The evidence reads other files (the props type's declarations, a forwarding target's props), so it is read
        // while the answer's dependencies are recorded. A panic gathering it leaves it unknown, never the answer lost.
        let label = format!("relevance:{}", mapping.component_name);
        let evidence = crate::panic_guard::contain_panic(&label, || relevance_inputs::evidence(mapping, ctx, &entry));
        (entry, diagnostics, evidence)
    });
    deps.files.insert(crate::path_key::PathKey::from(mapping.file_path.as_path()));
    let evidence = evidence.map_err(|diagnostic| diagnostics.own.push(diagnostic)).ok();
    (entry, diagnostics, deps, evidence)
}

/// Resolve a `ComponentMapping` to a complete `ComponentEntry`.
///
/// Called in parallel via rayon — must be `Send + Sync` (all data is owned/Arc'd).
#[cfg(test)]
pub fn resolve_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> (ComponentEntry, Vec<Diagnostic>) {
    let (entry, diagnostics) = resolve_component_shared(mapping, ctx);
    (entry, diagnostics.flatten())
}

/// The entry of a candidate with nothing to document: no props and no layers, which the output leaves out.
fn unpublished_entry(mapping: &ComponentMapping) -> ComponentEntry {
    ComponentEntry {
        relevance: None,
        for pending in cache.pending.values() {
            pending.priority.cancel();
        }
        cache.pending.clear();
        cache.props = PropInterner::default();
        self.provider.changed(change);
    }

    /// Cancels the requests in flight for `keys` that nobody waits for: the client no longer shows those components,
    /// so a checker that has not started them drops them. A later request asks again rather than joining a cancelled
    /// one; a request someone waits for, or one the checker is already converting, stays registered, so a later request
    /// joins it, and is answered (and kept) as before.
    pub(crate) fn cancel(&self, keys: &[String]) {
        let keys: FxHashSet<&str> = keys.iter().map(String::as_str).collect();
        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
        cache.pending.retain(|(key, _), pending| !(keys.contains(key.as_str()) && pending.priority.cancel()));
    }

    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
    pub(crate) fn refine(
        &self,
        mut answer: ComponentAnswer,
        mode: HtmlAttributeMode,
        cx: CollapseContext,
        priority: Priority,
    ) -> ComponentAnswer {
